import blockList from '../content/blocks.json'

// Every vanilla block ID with its English name, for the block-type autocomplete.
// Generated by `npm run update:blocks` from Mojang's registry and committed, so
// nothing is fetched at runtime. Suggestions only: the input stays free-text,
// so modded blocks and anything newer than this snapshot still scan.

export type BlockType = { id: string; name: string }

export const BLOCKS_VERSION: string = blockList.version

export const BLOCK_TYPES: BlockType[] = blockList.blocks.map(([id, name]) => ({
  id: `minecraft:${id}`,
  name,
}))

const NAMES = new Map(BLOCK_TYPES.map((block) => [block.id, block.name]))

/** The English name for a namespaced ID, or null for modded/unknown blocks. */
export const blockName = (id: string): string | null => NAMES.get(id) ?? null
